FUNCTION_BLOCK FB_AnalogScale
VAR_INPUT
    Raw : INT;
    RawMin : INT := 0;
    RawMax : INT := 27648;
    EngMin : REAL := 0.0;
    EngMax : REAL := 100.0;
END_VAR
VAR_OUTPUT
    Value : REAL;
    WireBreak : BOOL;
END_VAR

WireBreak := Raw < (RawMin - 1000);
Value := EngMin + (INT_TO_REAL(Raw - RawMin) / INT_TO_REAL(RawMax - RawMin)) * (EngMax - EngMin);
END_FUNCTION_BLOCK
